import{_ as e,r,o as t,c as o,a as i,b as h,d as n,e as p}from"./app.ChrdILIc.js";import"./chunks/three-vendor.DK3fmyXa.js";const f=JSON.parse('{"title":"AI","description":"","frontmatter":{},"headers":[],"relativePath":"zh/ai/preface.md","filePath":"zh/ai/preface.md","lastUpdated":1778395361000}'),u={name:"zh/ai/preface.md"};function d(s,l,c,b,m,q){const a=r("ArticleMetadata");return t(),o("div",null,[l[0]||(l[0]=i("h1",{id:"ai",tabindex:"-1"},[h("AI "),i("a",{class:"header-anchor",href:"#ai","aria-label":'Permalink to "AI"'},"​")],-1)),n(a),l[1]||(l[1]=p('<h2 id="对-ai-的态度建议" tabindex="-1">对 AI 的态度建议 <a class="header-anchor" href="#对-ai-的态度建议" aria-label="Permalink to &quot;对 AI 的态度建议&quot;">​</a></h2><p>面对 AI，团队更推荐的态度不是观望，也不是浅尝辄止，而是 <strong>全面、快速、持续地拥抱 AI，并主动把它接入工作与生活</strong>。</p><p>这并不意味着盲目迷信 AI，而是要把 AI 当成一种新的基础能力，就像过去我们拥抱搜索引擎、移动互联网、云服务一样，把它真正纳入日常习惯、业务流程和个人成长体系中。</p><p>建议从以下几个方向形成共识：</p><ul><li><strong>先用起来，再持续优化</strong>：不要等到“完全懂了”才开始，先把 AI 用在写作、总结、翻译、搜索、编程、做表、整理信息等高频场景。</li><li><strong>让 AI 进入工作主流程</strong>：不要只把 AI 当聊天工具，而要让它进入销售、客服、申请、培训、文档、研发、运营等关键链路。</li><li><strong>让 AI 进入个人生活</strong>：可以用于日程安排、学习规划、信息整理、旅行准备、健康记录、语言练习、消费决策等日常事务。</li><li><strong>保持开放和迭代心态</strong>：模型、工具、交互方式变化很快，重要的不是一次选对，而是持续试用、持续更新、持续升级认知。</li><li><strong>既积极拥抱，也保留判断</strong>：快速使用 AI，但不放弃人工判断、事实核验、安全意识和责任边界。</li></ul><p>如果一个团队还把 AI 当成“可选加分项”，往往会很快落后；更现实的判断是，AI 正在成为个人效率、组织协作和业务竞争力的基础设施。</p><h2 id="核心技术构成" tabindex="-1">核心技术构成 <a class="header-anchor" href="#核心技术构成" aria-label="Permalink to &quot;核心技术构成&quot;">​</a></h2><h3 id="_1-大模型-llm" tabindex="-1">1. 大模型（LLM） <a class="header-anchor" href="#_1-大模型-llm" aria-label="Permalink to &quot;1. 大模型（LLM）&quot;">​</a></h3><p>大模型是 AI 模块的推理与生成核心，负责理解用户意图、生成自然语言、总结长文本、抽取结构化信息、改写文档和辅助决策。</p><p>在业务中可承担：</p><ul><li>销售沟通总结与话术生成</li><li>客户问题解答与政策说明</li><li>申请文书润色与结构优化</li><li>多轮对话中的上下文理解</li><li>表单内容补全、归纳、纠错</li></ul><h3 id="_2-prompt-提示词" tabindex="-1">2. Prompt（提示词） <a class="header-anchor" href="#_2-prompt-提示词" aria-label="Permalink to &quot;2. Prompt（提示词）&quot;">​</a></h3><p>Prompt 是对模型行为的约束层。一个好的 Prompt 不只是“提问”，而是把角色、目标、输入、限制条件、输出格式、风格要求、风险提示全部结构化表达。</p><p>项目中建议按场景沉淀 Prompt 模板，例如：</p><ul><li>销售培训 Prompt</li><li>客户填表辅助 Prompt</li><li>文书优化 Prompt</li><li>题目解析与交叉验证 Prompt</li><li>客户沟通纪要总结 Prompt</li></ul><h3 id="_3-知识库" tabindex="-1">3. 知识库 <a class="header-anchor" href="#_3-知识库" aria-label="Permalink to &quot;3. 知识库&quot;">​</a></h3><p>知识库用于存放公司内部知识与业务资料，是 AI 回答“更像公司员工”的关键基础。相比纯模型直接回答，知识库能够让回答更贴近公司流程、产品、政策和历史经验。</p><p>典型知识来源包括：</p><ul><li>产品介绍、服务范围、套餐说明</li><li>销售 SOP、客服 SOP、申请服务流程</li><li>历史优秀案例、常见问题、内部培训资料</li><li>客户填表规范、材料清单、文书模板</li><li>制度文件、风控规则、审批要求</li></ul><h3 id="_4-rag-检索增强生成" tabindex="-1">4. RAG（检索增强生成） <a class="header-anchor" href="#_4-rag-检索增强生成" aria-label="Permalink to &quot;4. RAG（检索增强生成）&quot;">​</a></h3><p>RAG 是 AI 模块最重要的落地能力之一。它先从知识库中检索相关资料，再基于检索结果生成回答，比单纯依赖模型记忆更稳定、更可控。</p><p>RAG 适用于：</p><ul><li>基于最新业务规则回答客户问题</li><li>根据公司制度解释流程与审批要求</li><li>结合历史资料生成更贴合业务的建议</li><li>减少模型“编造答案”或答非所问</li></ul><h3 id="_5-向量检索" tabindex="-1">5. 向量检索 <a class="header-anchor" href="#_5-向量检索" aria-label="Permalink to &quot;5. 向量检索&quot;">​</a></h3><p>向量检索负责在大量资料中找到“语义最相关”的内容，而不仅仅依赖关键词。它是知识库问答、相似案例匹配、历史对话召回、重复问题识别的重要基础设施。</p><h3 id="_6-workflow-工作流" tabindex="-1">6. Workflow（工作流） <a class="header-anchor" href="#_6-workflow-工作流" aria-label="Permalink to &quot;6. Workflow（工作流）&quot;">​</a></h3><p>Workflow 用于把 AI 能力嵌入真实业务链路，而不是停留在聊天演示层。它负责定义触发条件、输入数据、处理步骤、审核节点、异常分支和最终输出。</p><p>例如：</p><ol><li>客户提交资料</li><li>系统自动校验字段完整性</li><li>AI 生成资料缺失清单与补充建议</li><li>客服人工确认后发送给客户</li><li>最终回写 CRM / 申请系统</li></ol><h3 id="_7-agent-智能体" tabindex="-1">7. Agent（智能体） <a class="header-anchor" href="#_7-agent-智能体" aria-label="Permalink to &quot;7. Agent（智能体）&quot;">​</a></h3><p>Agent 是在模型基础上具备“任务分解、工具调用、状态管理、执行反馈”的更高阶能力。它适合处理跨多个步骤、需要调用系统数据或外部工具的复杂任务。</p><p>项目中的 Agent 更适合做：</p><ul><li>销售助手：读取客户画像、跟进记录、产品知识，生成下一步跟进建议</li><li>客服助手：根据客户提交内容识别问题并给出回复草稿</li><li>文书助手：检查申请材料、补全要点、生成标准化文书初稿</li><li>题目助手：多模型分析、答案比对、置信度排序</li></ul><h2 id="项目中的-ai-模块设计建议" tabindex="-1">项目中的 AI 模块设计建议 <a class="header-anchor" href="#项目中的-ai-模块设计建议" aria-label="Permalink to &quot;项目中的 AI 模块设计建议&quot;">​</a></h2><h3 id="_1-销售培训与销售辅助" tabindex="-1">1. 销售培训与销售辅助 <a class="header-anchor" href="#_1-销售培训与销售辅助" aria-label="Permalink to &quot;1. 销售培训与销售辅助&quot;">​</a></h3><p>该能力不仅是“陪练聊天”，更应该形成一套可复用的销售训练系统。</p><p>建议覆盖：</p><ul><li>产品知识问答与考试</li><li>销售流程演练</li><li>异议处理与话术建议</li><li>客户画像分析与沟通策略推荐</li><li>通话纪要总结与跟进建议生成</li><li>优秀案例沉淀与复盘</li></ul><p>预期价值：</p><ul><li>新人上手更快</li><li>销售口径更统一</li><li>高质量话术可以复制</li><li>客户跟进效率和转化率提升</li></ul><h3 id="_2-客户填表与咨询辅助" tabindex="-1">2. 客户填表与咨询辅助 <a class="header-anchor" href="#_2-客户填表与咨询辅助" aria-label="Permalink to &quot;2. 客户填表与咨询辅助&quot;">​</a></h3><p>客户在填写表单、准备材料、理解术语时通常最容易流失，因此该能力应强调“降低门槛”和“即时引导”。</p><p>建议覆盖：</p><ul><li>表单字段解释</li><li>根据历史输入智能补全内容</li><li>检查格式、语义和逻辑错误</li><li>用更易懂的语言解释专业术语</li><li>提醒缺漏项与不一致项</li><li>多语言或口语化重写</li></ul><p>预期价值：</p><ul><li>降低客户填写难度</li><li>减少客服重复解释成本</li><li>提升资料一次性提交完整率</li></ul><h3 id="_3-文书优化与申请辅助" tabindex="-1">3. 文书优化与申请辅助 <a class="header-anchor" href="#_3-文书优化与申请辅助" aria-label="Permalink to &quot;3. 文书优化与申请辅助&quot;">​</a></h3><p>文书优化不能只做“润色”，还应包含结构检查、逻辑补全、风格统一和风险提示。</p><p>建议覆盖：</p><ul><li>自动生成文书草稿</li><li>优化表达逻辑与语言质量</li><li>根据不同申请类型套用模板结构</li><li>检查是否缺少关键事实、时间、材料说明</li><li>统一格式、标题、语气和规范性表达</li><li>标记高风险描述，提醒人工复核</li></ul><p>预期价值：</p><ul><li>提高文书质量与一致性</li><li>缩短顾问和文案的处理时间</li><li>减少低级错误与遗漏</li></ul><h3 id="_4-做题与内容验证服务" tabindex="-1">4. 做题与内容验证服务 <a class="header-anchor" href="#_4-做题与内容验证服务" aria-label="Permalink to &quot;4. 做题与内容验证服务&quot;">​</a></h3><p>这一能力适合用于题目解析、培训考试、知识考核、政策理解等场景，重点不是“直接给答案”，而是“提升答案可靠性”。</p><p>建议覆盖：</p><ul><li>多模型并行回答</li><li>关键步骤解释</li><li>参考依据标注</li><li>交叉验证与分歧提醒</li><li>输出置信度与推荐答案</li><li>对明显不确定内容给出人工复核提示</li></ul><p>预期价值：</p><ul><li>降低模型幻觉带来的误导</li><li>提高培训学习与题目服务质量</li><li>让答案更透明、更可追踪</li></ul><h2 id="推荐的-ai-架构分层" tabindex="-1">推荐的 AI 架构分层 <a class="header-anchor" href="#推荐的-ai-架构分层" aria-label="Permalink to &quot;推荐的 AI 架构分层&quot;">​</a></h2><h3 id="交互层" tabindex="-1">交互层 <a class="header-anchor" href="#交互层" aria-label="Permalink to &quot;交互层&quot;">​</a></h3><ul><li>Web 页面、表单页面、客服工作台、销售工作台、内部运营后台</li><li>支持聊天式交互、表单辅助、按钮触发、批量处理等入口</li></ul><h3 id="能力编排层" tabindex="-1">能力编排层 <a class="header-anchor" href="#能力编排层" aria-label="Permalink to &quot;能力编排层&quot;">​</a></h3><ul><li>Prompt 模板管理</li><li>工作流编排</li><li>模型路由</li><li>任务队列</li><li>审核与回写机制</li></ul><h3 id="智能能力层" tabindex="-1">智能能力层 <a class="header-anchor" href="#智能能力层" aria-label="Permalink to &quot;智能能力层&quot;">​</a></h3><ul><li>通用大模型</li><li>专项任务模型</li><li>文本抽取与分类能力</li><li>检索与知识问答能力</li><li>多模型比对与验证能力</li></ul><h3 id="数据与知识层" tabindex="-1">数据与知识层 <a class="header-anchor" href="#数据与知识层" aria-label="Permalink to &quot;数据与知识层&quot;">​</a></h3><ul><li>客户数据</li><li>产品数据</li><li>销售/客服/申请知识库</li><li>文书模板库</li><li>历史对话、案例与行为日志</li></ul><h3 id="治理与安全层" tabindex="-1">治理与安全层 <a class="header-anchor" href="#治理与安全层" aria-label="Permalink to &quot;治理与安全层&quot;">​</a></h3><ul><li>权限控制</li><li>敏感信息脱敏</li><li>审计日志</li><li>结果追踪</li><li>人工审核</li><li>风险告警</li></ul><h2 id="模型选择策略" tabindex="-1">模型选择策略 <a class="header-anchor" href="#模型选择策略" aria-label="Permalink to &quot;模型选择策略&quot;">​</a></h2><p>AI 模块不建议只依赖单一模型，而应根据任务类型做模型路由。</p><p>可按以下方式拆分：</p><ul><li>通用对话模型：处理咨询、总结、润色、问答</li><li>强推理模型：处理复杂分析、题目解析、对比判断</li><li>低成本快速模型：处理批量改写、摘要、分类、标签提取</li><li>本地模型：处理隐私敏感或内网场景</li><li>多模态模型：处理图片、截图、材料识别等场景</li></ul><h2 id="为什么需要多模型能力" tabindex="-1">为什么需要多模型能力 <a class="header-anchor" href="#为什么需要多模型能力" aria-label="Permalink to &quot;为什么需要多模型能力&quot;">​</a></h2><p>多模型并行不是为了“炫技”，而是为了平衡四件事：</p><ul><li>质量：复杂问题优先高能力模型</li><li>成本：简单任务优先低成本模型</li><li>速度：实时交互优先响应更快的模型</li><li>稳定性：主模型异常时可切换回退模型</li></ul><h2 id="ai-技能与工具调用" tabindex="-1">AI 技能与工具调用 <a class="header-anchor" href="#ai-技能与工具调用" aria-label="Permalink to &quot;AI 技能与工具调用&quot;">​</a></h2><p>当模型需要访问真实系统数据、执行真实操作时，仅靠自然语言回答是不够的，还需要工具调用能力。</p><p>项目中可扩展的 AI 技能包括：</p><ul><li>查询客户档案</li><li>读取订单状态</li><li>生成客户跟进摘要</li><li>检查资料缺失项</li><li>读取知识库片段</li><li>触发消息通知</li><li>生成表格、文书或任务清单</li></ul><p>这类能力是 AI 从“能说”走向“能干”的关键。</p><h2 id="模型上下文协议-mcp" tabindex="-1">模型上下文协议（MCP） <a class="header-anchor" href="#模型上下文协议-mcp" aria-label="Permalink to &quot;模型上下文协议（MCP）&quot;">​</a></h2><p>MCP 是面向模型的标准化上下文接入协议，可以理解为 AI 与外部工具、数据源、业务系统之间的统一连接方式。对于未来需要接入多种内部服务、知识源和自动化工具的项目来说，MCP 具有较强的扩展价值。</p><p>在企业场景中，MCP 的意义主要在于：</p><ul><li>统一模型访问外部资源的方式</li><li>降低后续接入新工具、新系统的改造成本</li><li>提升上下文传递、工具调用和权限管理的一致性</li></ul><h2 id="安全、风控与治理" tabindex="-1">安全、风控与治理 <a class="header-anchor" href="#安全、风控与治理" aria-label="Permalink to &quot;安全、风控与治理&quot;">​</a></h2><p>AI 模块上线后，真正难的不是“能不能生成”，而是“能不能安全稳定地生成”。</p><p>必须重点关注：</p><ul><li>隐私与数据安全：客户资料、合同、财务、身份证明等敏感信息必须分级管理。</li><li>权限隔离：不同角色能看到和调用的 AI 能力应不同。</li><li>审计追踪：保留提示词、输入摘要、输出结果、人工确认记录。</li><li>幻觉控制：涉及政策、申请、财务、合同的回答必须结合知识库与人工复核。</li><li>风险提示：对不确定、依据不足、可能违规的内容明确标注。</li><li>成本控制：建立调用频次、Token 消耗、模型路由与缓存策略。</li></ul><h2 id="实施优先级建议" tabindex="-1">实施优先级建议 <a class="header-anchor" href="#实施优先级建议" aria-label="Permalink to &quot;实施优先级建议&quot;">​</a></h2><p>从项目落地角度，建议按“低风险高价值”优先实施：</p><ol><li>客户填表辅助</li><li>销售知识问答与培训</li><li>文书优化与标准模板生成</li><li>客户沟通纪要总结与 CRM 回写</li><li>多模型题目解析与交叉验证</li><li>更复杂的 Agent 自动化能力</li></ol><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p>AI 模块的核心不是接一个聊天机器人，而是围绕“知识、流程、场景、治理”构建一套可持续演进的业务智能系统，让 AI 真正成为销售、客服、申请服务和管理流程中的生产力工具。</p>',94))])}const _=e(u,[["render",d]]);export{f as __pageData,_ as default};
